  const loaded = yield* external.loadShipping(request.purchase, original, selectedOffer, at);
  const delivery = yield* Schema.decodeUnknownEffect(Schema.toType(PromotionSelectedDeliveryFactsSchema))(
    loaded.delivery,
  ).pipe(
    Effect.mapError(
      (cause) =>
        new PromotionEvaluationFailure({
          cause,
          code: 'UNVERIFIABLE',
          reason: 'Chosen Delivery evidence cannot be decoded',
        }),
    ),
  );
  const sameRef = Schema.toEquivalence(PromotionDeliveryMethodRefSchema);
  if (
    !samePurchase(delivery.purchase, request.purchase) ||
    !sameRef(delivery.offerRef, selectedOffer) ||
    !fresh(delivery, at) ||
    delivery.tenantId !== request.purchase.tenantId ||
    delivery.purchaseRef !== request.purchase.purchaseRef
  ) {
    return yield* failure('UNVERIFIABLE', 'Chosen Delivery Offer does not bind this exact Current purchase');
  }
  const verifiedPublication = yield* Option.match(loaded.publication, {
    onNone: () => Effect.succeed(Option.none<PromotionPublishedMerchandiseFacts>()),
    onSome: Effect.fn('PromotionEvaluation.publicationFacts')(function* publicationFacts(input) {
      const publication = yield* Schema.decodeUnknownEffect(Schema.toType(PromotionPublishedMerchandiseFactsSchema))(
        input,
      ).pipe(
        Effect.mapError(
          (cause) =>
            new PromotionEvaluationFailure({
              cause,
              code: 'UNVERIFIABLE',
              reason: 'Published merchandise evidence cannot be decoded',
            }),
        ),
      );
      if (
        !samePurchase(publication.purchase, request.purchase) ||
        publication.merchandiseProofId !== original.proofId ||
        publication.mode !== original.merchandise.basis.mode ||
        !fresh(publication, at) ||
        publication.tenantId !== request.purchase.tenantId ||
        publication.purchaseRef !== request.purchase.purchaseRef
      ) {
        return yield* failure(
          'UNVERIFIABLE',
          'Publication must bind the same monetary proof, purchase and resolved basis',
        );
      }
      return Option.some(publication);
    }),
  });
